const IntrinsicReflectApply = Reflect.apply;
const IntrinsicWeakMap = WeakMap;
const ObjectFreeze = Object.freeze;
const WeakMapGet = WeakMap.prototype.get;
const WeakMapSet = WeakMap.prototype.set;
/** Create an internal WeakMap facade with non-replaceable operations. */
export function createPrivateWeakStore() {
    const store = new IntrinsicWeakMap();
    return ObjectFreeze({
        get(key) {
            return IntrinsicReflectApply(WeakMapGet, store, [key]);
        },
        set(key, value) {
            IntrinsicReflectApply(WeakMapSet, store, [key, value]);
        },
    });
}
